@gene('Z7b', 'an enemy champion or an awake camp is close to me', parents=['s1'])
def in_fight() -> Bool:
    p = me().pos
    if any(dist(u.pos, p) <= 4 for u in enemies()):
        return True
    return any(is_awake(u) and dist(u.pos, p) <= u.attack_range + 1 for u in camps())

@gene('Z27a', 'how far a tile sits outside the reach of the nearest awake camp or visible enemy champion (plus 5), so fleeing steps clear the longest reach first', parents=['Z7b'])
def threat_dist(t: Tile) -> Num:
    a = min((dist(u.pos, t) - u.attack_range for u in camps() if is_awake(u)), default=99)
    b = min((dist(u.pos, t) - u.attack_range for u in enemies()), default=99)
    return min(a, b) + 5
